import zipfile
from xml.etree import ElementTree as ET

z = zipfile.ZipFile('budget.xlsx')
ns = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

rows = []
for row in root.findall('.//m:row', ns):
    r = int(row.get('r'))
    cells = {}
    for c in row.findall('m:c', ns):
        ref = c.get('r')
        t = c.get('t')
        v = c.find('m:v', ns)
        istr = c.find('m:is', ns)
        if istr is not None:
            txt = ''.join(x.text or '' for x in istr.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            cells[ref] = ('str', txt)
        elif v is not None:
            cells[ref] = ('num', float(v.text))
        else:
            f = c.find('m:f', ns)
            cells[ref] = ('formula', f.text if f is not None else None)
    rows.append((r, cells))

def get(cells, col, default=''):
    for ref, val in cells.items():
        if ref.startswith(col):
            return val
    return ('str', default)

print(f"{'Row':<4}{'Category':<16}{'Item':<22}{'Amount':>10}")
expense_rows = []
for r, cells in rows:
    a = get(cells, 'A')
    b = get(cells, 'B')
    c = get(cells, 'C')
    cat = a[1] if a[0]=='str' else a[1]
    item = b[1] if b[0]=='str' else ''
    amt = c[1] if c[0]=='num' else ''
    print(f"{r:<4}{cat:<16}{item:<22}{amt:>10}")
    if 11 <= r <= 22 and c[0] == 'num':
        expense_rows.append((cat, item, c[1]))

total = sum(x[2] for x in expense_rows)
print("\nAll expense line items (rows 11-22):")
for cat, item, amt in expense_rows:
    print(f"  {cat:<16}{item:<22}{amt:>10,.2f}")
print(f"\nTOTAL EXPENSES (sum of rows 11-22): {total:,.2f}")

by_cat = {}
for cat, item, amt in expense_rows:
    by_cat[cat] = by_cat.get(cat, 0) + amt
print("\nBy category:")
for k, v in by_cat.items():
    print(f"  {k:<16}{v:>10,.2f}")

# Also check the file's own formula totals
for r, cells in rows:
    for ref, val in cells.items():
        if val[0] == 'formula':
            print(f"\nFile formula at {ref}: ={val[1]}")
EOF
